SELECT JSON_OBJECT('table','npc_spells','row',JSON_OBJECT('id',ns.`id`,'name',ns.`name`,'parent_list',ns.`parent_list`,'attack_proc',ns.`attack_proc`,'proc_chance',ns.`proc_chance`,'range_proc',ns.`range_proc`,'rproc_chance',ns.`rproc_chance`,'defensive_proc',ns.`defensive_proc`,'dproc_chance',ns.`dproc_chance`,'fail_recast',ns.`fail_recast`,'engaged_no_sp_recast_min',ns.`engaged_no_sp_recast_min`,'engaged_no_sp_recast_max',ns.`engaged_no_sp_recast_max`,'engaged_b_self_chance',ns.`engaged_b_self_chance`,'engaged_b_other_chance',ns.`engaged_b_other_chance`,'engaged_d_chance',ns.`engaged_d_chance`,'pursue_no_sp_recast_min',ns.`pursue_no_sp_recast_min`,'pursue_no_sp_recast_max',ns.`pursue_no_sp_recast_max`,'pursue_d_chance',ns.`pursue_d_chance`,'idle_no_sp_recast_min',ns.`idle_no_sp_recast_min`,'idle_no_sp_recast_max',ns.`idle_no_sp_recast_max`,'idle_b_chance',ns.`idle_b_chance`)) FROM npc_spells ns WHERE ns.id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001) UNION SELECT parent_list FROM npc_spells WHERE id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001)));
SELECT JSON_OBJECT('table','npc_spells_entries','row',JSON_OBJECT('id',ne.`id`,'npc_spells_id',ne.`npc_spells_id`,'spellid',ne.`spellid`,'type',ne.`type`,'minlevel',ne.`minlevel`,'maxlevel',ne.`maxlevel`,'manacost',ne.`manacost`,'recast_delay',ne.`recast_delay`,'priority',ne.`priority`,'resist_adjust',ne.`resist_adjust`,'min_hp',ne.`min_hp`,'max_hp',ne.`max_hp`,'min_expansion',ne.`min_expansion`,'max_expansion',ne.`max_expansion`,'content_flags',ne.`content_flags`,'content_flags_disabled',ne.`content_flags_disabled`)) FROM npc_spells_entries ne WHERE ne.npc_spells_id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001) UNION SELECT parent_list FROM npc_spells WHERE id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001)));
WITH RECURSIVE eligible_items AS (
SELECT i.* FROM items i WHERE i.id<800000 AND i.slots>0 AND MOD(i.id,200000) IN (SELECT item_id FROM (SELECT DISTINCT ld.item_id, z.short_name AS zone, n.id AS npc_id,
n.name AS npc_name, n.level AS npc_level
FROM zone z JOIN spawn2 s ON s.zone=z.short_name AND s.version=z.version
JOIN spawnentry se ON se.spawngroupID=s.spawngroupID
JOIN npc_types n ON n.id=se.npcID
JOIN loottable l ON l.id=n.loottable_id
JOIN loottable_entries lt ON lt.loottable_id=l.id
JOIN lootdrop d ON d.id=lt.lootdrop_id
JOIN lootdrop_entries ld ON ld.lootdrop_id=lt.lootdrop_id
WHERE z.expansion=0 AND z.version=0 AND s._condition=0
AND NOT EXISTS (SELECT 1 FROM spawn2_disabled sd WHERE sd.spawn2_id=s.id AND sd.instance_id=0 AND sd.disabled<>0)
AND se.chance>0 AND lt.probability>0 AND lt.multiplier>0
AND ld.chance>0 AND ld.multiplier>0 AND ld.item_id BETWEEN 1 AND 199999
AND (ld.npc_min_level=0 OR n.level>=ld.npc_min_level)
AND (ld.npc_max_level=0 OR n.level<=ld.npc_max_level)
AND (s.min_expansion=-1 OR s.min_expansion=0) AND (s.max_expansion=-1 OR s.max_expansion>=0) AND COALESCE(s.content_flags,'')='' AND COALESCE(s.content_flags_disabled,'')='' AND (se.min_expansion=-1 OR se.min_expansion=0) AND (se.max_expansion=-1 OR se.max_expansion>=0) AND COALESCE(se.content_flags,'')='' AND COALESCE(se.content_flags_disabled,'')='' AND (ld.min_expansion=-1 OR ld.min_expansion=0) AND (ld.max_expansion=-1 OR ld.max_expansion>=0) AND COALESCE(ld.content_flags,'')='' AND COALESCE(ld.content_flags_disabled,'')=''
AND (l.min_expansion=-1 OR l.min_expansion=0) AND (l.max_expansion=-1 OR l.max_expansion>=0) AND COALESCE(l.content_flags,'')='' AND COALESCE(l.content_flags_disabled,'')='' AND (d.min_expansion=-1 OR d.min_expansion=0) AND (d.max_expansion=-1 OR d.max_expansion>=0) AND COALESCE(d.content_flags,'')='' AND COALESCE(d.content_flags_disabled,'')='') drop_sources)),
initial_refs(id) AS (SELECT id FROM spells_new WHERE id BETWEEN 1 AND 1200
UNION SELECT spellid FROM npc_spells_entries WHERE npc_spells_id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001) UNION SELECT parent_list FROM npc_spells WHERE id IN (SELECT npc_spells_id FROM npc_types WHERE id IN (32040,73057,64001)))
UNION SELECT clickeffect FROM eligible_items UNION SELECT worneffect FROM eligible_items UNION SELECT proceffect FROM eligible_items UNION SELECT focuseffect FROM eligible_items UNION SELECT scrolleffect FROM eligible_items UNION SELECT bardeffect FROM eligible_items), spell_refs(id) AS (
SELECT id FROM initial_refs WHERE id>0 AND id<65535
UNION SELECT s.RecourseLink FROM spells_new s JOIN spell_refs r ON s.id=r.id
WHERE s.RecourseLink>0 AND s.RecourseLink<65535)
