SELECT JSON_OBJECT('table','base_data','row',JSON_OBJECT('level',b.`level`,'class',b.`class`,'hp',b.`hp`,'mana',b.`mana`,'end',b.`end`,'hp_regen',b.`hp_regen`,'end_regen',b.`end_regen`,'hp_fac',b.`hp_fac`,'mana_fac',b.`mana_fac`,'end_fac',b.`end_fac`)) FROM base_data b WHERE b.level<=55;
SELECT JSON_OBJECT('table','skill_caps','row',JSON_OBJECT('id',sc.`id`,'skill_id',sc.`skill_id`,'class_id',sc.`class_id`,'level',sc.`level`,'cap',sc.`cap`,'class_',sc.`class_`)) FROM skill_caps sc WHERE sc.level<=55;
SELECT JSON_OBJECT('table','char_create_combinations','row',JSON_OBJECT('allocation_id',cc.`allocation_id`,'race',cc.`race`,'class',cc.`class`,'deity',cc.`deity`,'start_zone',cc.`start_zone`,'expansions_req',cc.`expansions_req`)) FROM char_create_combinations cc WHERE cc.race=1;
SELECT JSON_OBJECT('table','char_create_point_allocations','row',JSON_OBJECT('id',ca.`id`,'base_str',ca.`base_str`,'base_sta',ca.`base_sta`,'base_dex',ca.`base_dex`,'base_agi',ca.`base_agi`,'base_int',ca.`base_int`,'base_wis',ca.`base_wis`,'base_cha',ca.`base_cha`,'alloc_str',ca.`alloc_str`,'alloc_sta',ca.`alloc_sta`,'alloc_dex',ca.`alloc_dex`,'alloc_agi',ca.`alloc_agi`,'alloc_int',ca.`alloc_int`,'alloc_wis',ca.`alloc_wis`,'alloc_cha',ca.`alloc_cha`)) FROM char_create_point_allocations ca WHERE ca.id IN (SELECT allocation_id FROM char_create_combinations WHERE race=1);
SELECT JSON_OBJECT('table','rule_values','row',JSON_OBJECT('ruleset_id',r.ruleset_id,'rule_name',r.rule_name,'rule_value',r.rule_value)) FROM rule_values r WHERE r.ruleset_id IN (1,2) AND r.rule_name REGEXP '^(Character|Spells|Combat|NPC|Zone|Expansion|AA|Merchant|Aggro):';
SELECT JSON_OBJECT('table','drop_sources','row',JSON_OBJECT('item_id',item_id,'zone',zone,'npc_id',npc_id,'npc_name',npc_name,'npc_level',npc_level)) FROM (SELECT DISTINCT ld.item_id, z.short_name AS zone, n.id AS npc_id,
n.name AS npc_name, n.level AS npc_level
FROM zone z JOIN spawn2 s ON s.zone=z.short_name AND s.version=z.version
JOIN spawnentry se ON se.spawngroupID=s.spawngroupID
JOIN npc_types n ON n.id=se.npcID
JOIN loottable l ON l.id=n.loottable_id
JOIN loottable_entries lt ON lt.loottable_id=l.id
JOIN lootdrop d ON d.id=lt.lootdrop_id
JOIN lootdrop_entries ld ON ld.lootdrop_id=lt.lootdrop_id
WHERE z.expansion=0 AND z.version=0 AND s._condition=0
AND NOT EXISTS (SELECT 1 FROM spawn2_disabled sd WHERE sd.spawn2_id=s.id AND sd.instance_id=0 AND sd.disabled<>0)
AND se.chance>0 AND lt.probability>0 AND lt.multiplier>0
AND ld.chance>0 AND ld.multiplier>0 AND ld.item_id BETWEEN 1 AND 199999
AND (ld.npc_min_level=0 OR n.level>=ld.npc_min_level)
AND (ld.npc_max_level=0 OR n.level<=ld.npc_max_level)
AND (s.min_expansion=-1 OR s.min_expansion=0) AND (s.max_expansion=-1 OR s.max_expansion>=0) AND COALESCE(s.content_flags,'')='' AND COALESCE(s.content_flags_disabled,'')='' AND (se.min_expansion=-1 OR se.min_expansion=0) AND (se.max_expansion=-1 OR se.max_expansion>=0) AND COALESCE(se.content_flags,'')='' AND COALESCE(se.content_flags_disabled,'')='' AND (ld.min_expansion=-1 OR ld.min_expansion=0) AND (ld.max_expansion=-1 OR ld.max_expansion>=0) AND COALESCE(ld.content_flags,'')='' AND COALESCE(ld.content_flags_disabled,'')=''
AND (l.min_expansion=-1 OR l.min_expansion=0) AND (l.max_expansion=-1 OR l.max_expansion>=0) AND COALESCE(l.content_flags,'')='' AND COALESCE(l.content_flags_disabled,'')='' AND (d.min_expansion=-1 OR d.min_expansion=0) AND (d.max_expansion=-1 OR d.max_expansion>=0) AND COALESCE(d.content_flags,'')='' AND COALESCE(d.content_flags_disabled,'')='') sources ORDER BY item_id,zone,npc_id;
